from django.test import TestCase

from .genetic_algorithm import genetic_algorithm


class AdminPageTests(TestCase):
    def test_admin_login_page_is_available(self):
        response = self.client.get('/admin/login/')

        self.assertEqual(response.status_code, 200)


# TODO: Remove as generated by AI to help genetic algorithm mock generation
class GeneticAlgorithmTests(TestCase):
    def test_run_generates_population_of_valid_gene_permutations(self):
        parameters = {
            "bruteForce": False,
            "islands": 5,
            "boats": 12,
            "maxGenerations": 1,
            "mutationRate": 0.1,
            "crossoverRate": 0.8,
            "elitism": 0.1,
            "fitnessFunction": "euclidean",
        }
        algorithm = genetic_algorithm(parameters, {})

        algorithm.run()

        generation = algorithm.generation_record[0]
        self.assertEqual(len(generation["all"]), parameters["boats"])
        for individual in [
            generation["best"],
            generation["median"],
            generation["worst"],
            *generation["all"],
        ]:
            genes = individual["genes"]
            self.assertEqual(len(genes), parameters["islands"])
            self.assertEqual(set(genes), set("ABCDE"))
